import mailbox
mbox_path = "/home/user/.thunderbird/t5q2a5hp.default-release/Mail/Local Folders/daily"
mbox = mailbox.mbox(mbox_path)
for i, msg in enumerate(mbox):
    print("---", i, msg.get('Subject', '')[:50], "---")
    if msg.is_multipart():
        for part in msg.walk():
            ct = part.get_content_type()
            cd = part.get('Content-Disposition', '')
            fn = part.get_filename()
            print(" ", ct, "| disp:", cd[:60] if cd else "", "| fn:", fn)
    else:
        print("  not multipart, content_type:", msg.get_content_type(), "filename:", msg.get_filename())
